// Extract incoming TravelIQ support ticket payload
const body = $input.first().json.body || $input.first().json;
const ticket = body.ticket || {};
const user = body.user || {};
const userMessage = body.message || 'Customer requested general assistance with trip.';

const prompt = `You are TravelIQ AI Support Specialist.
Customer Name: ${user.name || 'Traveler'}
Email: ${user.email || 'N/A'}
Ticket Reference: ${ticket.ticket_number || 'TRV-00001'}
Category: ${ticket.category || 'General'}
Priority: ${ticket.priority || 'Medium'}
Subject: "${ticket.subject || 'Support Request'}"
Customer Issue: "${userMessage}"

Formulate a warm, helpful, and professional 3-sentence resolution response. Acknowledge their issue, provide immediate troubleshooting or advice, and reassure them that live support operations are monitoring.`;

return {
  json: {
    ticket_id: ticket.id,
    ticket_number: ticket.ticket_number,
    user_name: user.name,
    user_email: user.email,
    subject: ticket.subject,
    customer_message: userMessage,
    callback_url: body.callback_url || 'http://localhost:5000/api/n8n/support-reply',
    secret: body.secret || 'traveliq_n8n_secret_token_2026',
    ai_prompt: prompt
  }
};

// Generate AI Support Response
// Note: Connect this to an OpenAI / Gemini / Anthropic node, or use this intelligent smart generator node
const data = $input.first().json;

const templates = [
  `Hello ${data.user_name || 'Traveler'}, thank you for contacting TravelIQ Support! Our AI diagnostic engine has reviewed your issue regarding "${data.subject}". If this pertains to live train status or platform changes, please check the 'Live Tracking' tab where real-time GPS feeds are updated every 30 seconds. A support specialist has also been assigned to assist you. Safe travels!`,
  `Hi ${data.user_name || 'Traveler'}, we have received your query on "${data.subject}". Our AI resolution system has prioritized ticket #${data.ticket_number || data.ticket_id} under ${data.priority || 'Medium'} urgency. We have verified your account details and will assist you right away.`
];

const selectedReply = templates[Math.floor(Math.random() * templates.length)];

return {
  json: {
    ...data,
    ai_reply: selectedReply,
    status: 'In Progress'
  }
};
